#include <stdio.h>
/*
 * ex07：进程地址空间的布局与「文件大小 ≠ 内存大小」
 *   高地址  +------------------+
 *           | 内核空间(用户态不可访问) |
 *           +------------------+
 *           | 栈 stack  (向下增长)   |
 *           | mmap 区(共享库/文件映射) |
 *           | 堆 heap   (向上增长)   |
 *           | bss 未初始化全局(清零)  |
 *           | data 已初始化全局       |
 *           | text 代码段(只读)       |
 *   低地址  +------------------+
 * 关键点：bss 在 ELF 文件里只存「大小」，不占磁盘；运行时却真的占内存。
 */
typedef struct {
    const char *seg;
    long file_bytes;   /* 在可执行文件里占多少字节 */
    long mem_bytes;    /* 装入后占多少内存 */
    const char *perm;
} Seg;

int main(void) {
    Seg segs[] = {
        {"text 代码段",     40960,  40960,  "r-x"},
        {"rodata 只读数据",  8192,   8192,  "r--"},
        {"data 已初始化",    2048,   2048,  "rw-"},
        {"bss 未初始化",        0, 4194304, "rw-"},   /* 4MB 全局数组，文件里大小为 0 */
        {"heap 堆",             0, 1048576, "rw-"},
        {"stack 栈",            0, 1048576, "rw-"},
        {"mmap 共享库",         0, 4194304, "r-x"}
    };
    int n = (int)(sizeof(segs) / sizeof(segs[0]));
    long fsum = 0, msum = 0;

    printf("%-16s %-14s %-14s %s\n", "段", "文件内字节", "内存中字节", "权限");
    printf("--------------------------------------------------------------\n");
    for (int i = 0; i < n; i++) {
        printf("%-16s %-14ld %-14ld %s\n", segs[i].seg, segs[i].file_bytes, segs[i].mem_bytes, segs[i].perm);
        fsum += segs[i].file_bytes;
        msum += segs[i].mem_bytes;
    }
    printf("--------------------------------------------------------------\n");
    printf("%-16s %-14ld %-14ld\n", "合计", fsum, msum);
    printf("\n文件大小 = %ld KB，运行时常驻虚拟内存 = %ld KB，膨胀 %.1f 倍\n",
           fsum / 1024, msum / 1024, (double)msum / fsum);
    printf("差异几乎全部来自 bss：int big[1048576]; 这种未初始化全局数组不占文件，但要占内存（且清零）。\n");
    return 0;
}
